<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class QualitySurvey extends Model { protected $fillable=['public_id','code','title','target_group','academic_year','purpose','frequency','opens_at','closes_at','expected_responses','responsible','form_url','is_mandatory','is_anonymous','response_policy','notes','is_active','status']; protected $casts=['is_mandatory'=>'boolean','is_anonymous'=>'boolean','is_active'=>'boolean','opens_at'=>'date','closes_at'=>'date']; public function questions(){return $this->hasMany(QualitySurveyQuestion::class);} public function responses(){return $this->hasMany(QualitySurveyResponse::class);} }
